def identity(payload):
    return payload
def box(payload):
    return {'value': payload}
def dispatch(table, key, payload):
    return table[key](payload)
handlers = {'read': identity, 'write': box}
payload = {}
direct = dispatch(handlers, 'read', payload)
boxed = dispatch(handlers, 'write', payload)
result = (direct is payload) and (boxed['value'] is payload)

